// Read-only asset qualification. It never retouches, clips or rewrites a candidate bitmap.
export function encodeAlphaRLE(alpha){const runs=[];for(const a of alpha){const last=runs.at(-1);if(last&&last[0]===a)last[1]++;else runs.push([a,1]);}return runs;}
export function decodeAlphaRLE(runs,length){const out=new Uint8Array(length);let n=0;for(const[value,count]of runs){if(!Number.isInteger(value)||value<0||value>255||!Number.isInteger(count)||count<1||n+count>length)throw Error('Invalid alpha contract');out.fill(value,n,n+count);n+=count;}if(n!==length)throw Error('Incomplete alpha contract');return out;}
export function qualifySpriteRGBA({width,height,rgba},contract){const result={dimensions:{actual:[width,height],expected:[contract.outputWidth,contract.outputHeight]},leakPixels:0,missingVisiblePixels:0,interiorOpacityFailures:0,gate:false};if(width!==contract.outputWidth||height!==contract.outputHeight){result.reason='canvas-dimensions';return result;}if(rgba.length!==width*height*4)throw Error('Invalid candidate RGBA');const ref=decodeAlphaRLE(contract.alphaRLE,contract.width*contract.height),s=contract.scale;let left=width,top=height,right=-1,bottom=-1;for(let y=0;y<height;y++)for(let x=0;x<width;x++){const a=rgba[(y*width+x)*4+3],expected=ref[Math.floor(y/s)*contract.width+Math.floor(x/s)];if(expected===0&&a>0)result.leakPixels++;if(expected>0&&a<128)result.missingVisiblePixels++;if(expected===255&&a<contract.minimumInteriorAlpha)result.interiorOpacityFailures++;if(a>=128){left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x+1);bottom=Math.max(bottom,y+1);}}result.visibleBBox=right<0?null:{left,top,right,bottom};result.expectedBBox=Object.fromEntries(Object.entries(contract.visibleBBox).map(([k,v])=>[k,v*s]));result.bboxDriftNative=result.visibleBBox?Object.fromEntries(Object.keys(result.expectedBBox).map(k=>[k,(result.visibleBBox[k]-result.expectedBBox[k])/s])):null;result.gate=result.leakPixels===0&&result.missingVisiblePixels===0&&result.interiorOpacityFailures===0;result.reason=result.gate?'exact-alpha-support':'alpha-or-silhouette';return result;}
